// The Warden commits to its target at windup: moving after the warning avoids impact.
const WARDEN_ATTACKS={volley:{name:'黒冠の矢',windup:.95,recovery:.7},slam:{name:'王の震撃',windup:1.2,recovery:.9},mark:{name:'灰の落星',windup:1.35,recovery:.75}};
function wardenBegin(e,kind){let def=WARDEN_ATTACKS[kind];e.state='attack';e.elapsed=0;e.struck=false;e.wardenAttack={kind,phase:e.phase||1,windup:def.windup,target:kind==='slam'?{x:e.x,y:e.y}:{x:p.x,y:p.y},radius:kind==='slam'?150:100};e.aim={...e.wardenAttack.target};if(typeof soundVoice==='function')soundVoice('sine',kind==='mark'?440:150,kind==='mark'?660:90,.5,.13);}
function wardenImpact(e){let a=e.wardenAttack;if(!a||e.struck||e.hp<=0)return;e.struck=true;
 if(a.kind==='volley'){let angle=Math.atan2(a.target.y-e.y,a.target.x-e.x),count=a.phase===2?7:5;for(let i=0;i<count;i++){let aim=angle+(i-(count-1)/2)*.21;shots.push({x:e.x,y:e.y,vx:Math.cos(aim)*240,vy:Math.sin(aim)*240,life:3,damage:17+floor*2,enemy:true})}}
 else{let t=a.target;if(dist(p,t)<=a.radius&&lineClear(t,p))hurt((a.kind==='slam'?30:25)+floor*3);burst(t.x,t.y,a.radius,a.kind==='slam'?'#f4bd77':'#c6a2ff');shake=Math.max(shake,5);if(typeof addEffect==='function')addEffect('sigil',t.x,t.y,{color:a.kind==='slam'?'#edb471':'#bf9bef',r:a.radius,duration:.6})}
 if(typeof soundVoice==='function')soundVoice('noise',.55,.2,.35,.2);
}
function animateWarden(e,dt){if(e.hp<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);e.t-=dt;e.nav-=dt;
 if(!e.phase)e.phase=1;if(e.hp<=e.max*.5&&e.phase===1){e.phase=2;say('黒冠が砕けた · 番人が激昂');feed('第二段階：攻撃の間隔が短くなる');if(typeof soundVoice==='function')soundVoice('sawtooth',90,35,.7,.15)}
 if(e.state==='attack'&&e.wardenAttack){let a=e.wardenAttack;e.elapsed+=dt;if(e.elapsed>=a.windup)wardenImpact(e);if(e.elapsed>=a.windup+WARDEN_ATTACKS[a.kind].recovery){e.state='idle';e.wardenAttack=null;e.t=e.phase===2?.45:.9}return}
 let d=dist(e,p);if(d>650){e.state='idle';return}let clear=lineClear(e,p);
 if(d<400&&clear&&e.t<=0){let cycle=e.cycle||0;e.cycle=cycle+1;wardenBegin(e,['volley','mark','slam'][cycle%3]);return}
 // Keep closing the gap between attacks; the slam remains stationary once warned.
 if(d<95&&clear){e.state='idle';return}if(e.nav<=0){e.nav=.5;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p)}let target=e.path?.[0];if(!target){e.state='idle';return}let dx=target.x-e.x,dy=target.y-e.y,len=Math.hypot(dx,dy);if(len<10){e.path.shift();return}let step=Math.min(len,(e.phase===2?95:75)*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,12)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;
}
const ordinaryEnemyAnimation=animateEnemy;animateEnemy=(e,dt)=>{if(e.boss)animateWarden(e,dt);else ordinaryEnemyAnimation(e,dt)};
function wardenWarning(e){let a=e.wardenAttack;if(!a||e.struck||!visibleAt(e.x,e.y))return;let progress=clamp(e.elapsed/a.windup,0,1),color=a.kind==='slam'?'#ffbd75':'#d1a9ff';ctx.save();ctx.strokeStyle=color;ctx.fillStyle=a.kind==='slam'?'#dd803333':'#a767d533';ctx.lineWidth=2;
 if(a.kind==='volley'){let angle=Math.atan2(a.target.y-e.y,a.target.x-e.x),count=a.phase===2?7:5;for(let i=0;i<count;i++){let aim=angle+(i-(count-1)/2)*.21,s=project(e.x,e.y),t=project(e.x+Math.cos(aim)*400,e.y+Math.sin(aim)*400);ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(t.x,t.y);ctx.stroke()}}
 else{let t=project(a.target.x,a.target.y);ctx.beginPath();ctx.ellipse(t.x,t.y,a.radius*ISOX*Math.SQRT2,a.radius*ISOY*Math.SQRT2,0,0,Math.PI*2);ctx.fill();ctx.stroke();groundRing(a.target.x,a.target.y,a.radius*progress,color,3)}
 ctx.restore();
}
const preWardenEffects=drawGroundEffects;drawGroundEffects=()=>{preWardenEffects();for(let e of enemies)if(e.boss&&e.hp>0)wardenWarning(e)};
function drawBossHud(){if(!started||!dungeon)return;let e=enemies.find(e=>e.boss&&e.hp>0&&dist(e,p)<650);if(!e)return;let width=Math.min(360,W*.4),x=(W-width)/2,y=e.exRank===100||['r1b0','r2b1','r2b2','r2b3','r4b1','r4b2'].includes(e.species)?H-210:92;ctx.save();ctx.fillStyle='#0a0c12e8';ctx.fillRect(x-12,y-27,width+24,64);ctx.strokeStyle='#b79b67';ctx.strokeRect(x-12,y-27,width+24,64);ctx.fillStyle='#e6cb96';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText((e.name||'黒冠の番人')+' · '+(e.phase===2?'激昂':'第一段階'),W/2,y-8);ctx.fillStyle='#302227';ctx.fillRect(x,y,width,9);ctx.fillStyle=e.phase===2?'#c0644e':'#a68b52';ctx.fillRect(x,y,width*clamp(e.hp/e.max,0,1),9);ctx.font='11px sans-serif';ctx.fillStyle='#d7c9ad';ctx.fillText(e.species==='r4b2'&&e.attack&&typeof azimAttackHint==='function'?azimAttackHint(e):e.species==='r4b1'&&e.attack&&typeof nefraAttackHint==='function'?nefraAttackHint(e):e.species==='r2b3'&&e.attack?.pattern==='aulGale'&&!e.struck?aulAttackHint(e):e.species==='r2b2'&&e.attack?.pattern==='noxHunt'&&!e.struck?noxAttackHint(e):e.species==='r2b1'&&e.attack?.pattern?.startsWith('rose')&&!e.struck?roseAttackHint(e):e.species==='r2b0'&&e.attack?.pattern?.startsWith('eldra')&&!e.struck?eldraAttackHint(e):e.species==='ex100skill'&&e.attack&&!e.struck?'星紡ぎの連星 · 固定円を離れ、弾の隙間へ':e.species==='r1b2'&&VAL_MOVES[e.attack?.pattern]&&!e.struck?VAL_MOVES[e.attack.pattern].name+' · '+VAL_MOVES[e.attack.pattern].hint:e.species==='r1b1'&&e.attack?.pattern==='selenePrism'&&!e.struck?seleneAttackHint(e):e.species==='r1b0'&&GRANITO_MOVES[e.attack?.pattern]&&!e.struck?GRANITO_MOVES[e.attack.pattern].name+' · '+GRANITO_MOVES[e.attack.pattern].hint:e.species==='r1b3'&&ORM_MOVES[e.attack?.pattern]&&!e.struck?ORM_MOVES[e.attack.pattern].name+' · '+ORM_MOVES[e.attack.pattern].hint:e.species==='r0b3'&&GARUDA_MOVES[e.attack?.pattern]&&!e.struck?GARUDA_MOVES[e.attack.pattern].name+' · '+GARUDA_MOVES[e.attack.pattern].hint:e.species==='r0b2'&&ROOK_MOVES[e.attack?.pattern]&&!e.struck?ROOK_MOVES[e.attack.pattern].name+' · '+ROOK_MOVES[e.attack.pattern].hint:e.species==='r0b0'&&FEN_MOVES[e.attack?.pattern]&&!e.struck?FEN_MOVES[e.attack.pattern].name+' · '+FEN_MOVES[e.attack.pattern].hint:e.species==='r0b1'&&BEHEMOTH_MOVES[e.attack?.pattern]&&!e.struck?BEHEMOTH_MOVES[e.attack.pattern].name+' · '+BEHEMOTH_MOVES[e.attack.pattern].hint:e.attack?.final&&!e.struck?FINAL_ATTACKS[e.attack.pattern].name+' · '+FINAL_ATTACKS[e.attack.pattern].hint:e.wardenAttack&&!e.struck?WARDEN_ATTACKS[e.wardenAttack.kind].name+' · 予兆の範囲から離れる':'攻撃後の隙を狙う',W/2,y+26);ctx.restore()};


const wardenLabelBase=drawEffects;drawEffects=()=>{wardenLabelBase();for(let e of enemies){let a=e.wardenAttack;if(!e.boss||e.hp<=0||!a||e.struck||!visibleAt(e.x,e.y))continue;ctx.save(); let label=project(a.target.x,a.target.y);ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff0d0';ctx.fillText(WARDEN_ATTACKS[a.kind].name,label.x,label.y-35);ctx.restore();}};



